mermaid:
classDiagram
    class SddServer {
        +start(port: Number): Promise~Number~
        +handleRequest(req: Request, res: Response)
        +broadcastEvent(event: String, payload: Object)
    }
    class ProjectModelV2 {
        +meta: Object
        +core: Object
        +requirements: Object
        +architecture: Object
        +normalize(rawState: Object): Object
        +calculateProgress(): Number
    }
    class McpServer {
        +tools: Array~Tool~
        +handleJsonRpc(msg: Object): Object
        +dispatchTask(storyId: String): Object
    }
    class ScopeShield {
        +scopeFiles: Array~String~
        +verifyGitDrift(projectRoot: String): Object
        +isAllowedPath(targetPath: String): Boolean
    }
    class ScannerEngine {
        +scanProject(root: String): Object
        +detectRoutes(root: String): Array
        +inferArchitecture(root: String): Object
    }
    SddServer --> ProjectModelV2 : Gestiona y expone
    SddServer --> ScannerEngine : Ejecuta analisis
    McpServer --> ScopeShield : Aplica reglas de deriva
    McpServer --> ProjectModelV2 : Lee Única Fuente de Verdad

classDiagram
    class ElementoMetamodelo {
        <<metaclass>>
        +nombre: String
    }
    class Estereotipo_SpecFile {
        <<stereotype>>
        +formato: "json"
        +atomico: Boolean
        +fuenteDeVerdad: true
    }
    class Estereotipo_QualityGate {
        <<stereotype>>
        +severidad: "mandatory"
        +aprobadoPorHumano: Boolean
        +bloqueaCodigo: Boolean
    }
    class Estereotipo_ScopeProtected {
        <<stereotype>>
        +scopeFiles: List~Path~
        +toleranciaDeriva: 0
    }
    class Estereotipo_GherkinCriteria {
        <<stereotype>>
        +dado: String
        +cuando: String
        +entonces: String
        +done: Boolean
    }
    ElementoMetamodelo <|-- Estereotipo_SpecFile : extiende
    ElementoMetamodelo <|-- Estereotipo_QualityGate : extiende
    ElementoMetamodelo <|-- Estereotipo_ScopeProtected : extiende
    ElementoMetamodelo <|-- Estereotipo_GherkinCriteria : extiende
